mapper.select:
SELECT 
FROM biz_guide_sheet_progress p
INNER JOIN biz_student s ON s.student_id = p.student_id
INNER JOIN sys_user u ON u.user_id = s.user_id
LEFT JOIN biz_guide_sheet_answer ans
       ON ans.binding_id = p.binding_id
      AND ans.student_id = p.student_id
WHERE p.binding_id = #{bindingId}
  AND p.dept_id = #{deptId}
  AND p.entry_year = #{entryYear}
  AND p.class_code = #{classCode}
ORDER BY s.student_no, p.student_id

SELECT id, binding_id, student_id, dept_id, entry_year, class_code,
       current_page, is_submitted, last_heartbeat, progress_detail
FROM biz_guide_sheet_progress
WHERE binding_id = #{bindingId}
  AND student_id = #{studentId}
